"use client";

import { useEffect, useId, useRef, useState, type ChangeEvent, type ComponentProps } from "react";

import { IconAlertCircle, IconArrowLeftRight, IconCheck, IconChevronsUpDown, IconLock } from "@rhs-ui/icons";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@rhs-ui/primitives/command";
import { trackPress, whenReleased } from "@rhs-ui/primitives/currency-exchange-field/blur-guard";
import {
  currencyDigits,
  currencyName,
  DEFAULT_CURRENCIES,
  DEFAULT_LABELS,
  feeOn,
  flatOf,
  formatAmount,
  formatMoneyText,
  limitOf,
  parseAmount,
  resolveValue,
  tidyTyping,
  writeRate,
  writeTime,
  type ExchangeLabels,
  type ExchangeLimit,
  type ExchangeValue,
  type FeeSource,
  type Leg,
  type Rates,
  type Side,
} from "@rhs-ui/primitives/currency-exchange-field/exchange";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type { ExchangeFee, ExchangeLabels, ExchangeLimit, ExchangeValue, FeeSource, Leg, RateFunction, RateTable, Rates, Side } from "@rhs-ui/primitives/currency-exchange-field/exchange";

export interface CurrencyExchangeFieldProps extends Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "children"> {
  /** Both amounts and the one that is fixed, when you control the field. Only the fixed amount and the two currencies are read: the other amount is always worked out from the rate. */
  value?: ExchangeValue;
  /** The amounts to start with, when you do not control the field. */
  defaultValue?: ExchangeValue;
  /**
   * Called whenever an amount, a currency or the rate changes, with both amounts in minor units (`{ send, receive, fixed }`)
   * and `valid` true once there is an amount to send, a rate, and the amount is inside `min` and `max`.
   */
  onValueChange?: (value: ExchangeValue, state: { valid: boolean }) => void;
  /** The rates: a table (`{ EUR: { USD: 1.0842 } }`, a missing pair is taken from the other way round) or a function `(from, to) => rate`. A new value is picked up at once, so live rates just work. */
  rates: Rates;
  /** The ISO codes in the two menus, in order. The first two are chosen at the start. Default: seven common ones. */
  currencies?: readonly string[];
  /**
   * What sending costs, taken off what is sent before the rate is applied: `{ percent, flat, label }`, or a function from what is sent to the fee in minor units. Shown in a row under the amounts.
   * `flat` follows the rule of `min` and `max`: a bare number is in the minor units of whichever currency is sent, so give one figure per currency code when several can be sent.
   */
  fee?: FeeSource;
  /** The locale that writes the amounts, names the currencies and decides the decimal sign. Default "en-US". */
  locale?: string;
  /** The lowest amount that can be sent. A bare number is in the minor units of whichever currency is sent (1000 is 10.00 in euros and 1,000 in yen), so give one figure per currency code when several can be sent. */
  min?: ExchangeLimit;
  /** The highest amount that can be sent, in minor units like `min`: a bare number, or one figure per currency code. */
  max?: ExchangeLimit;
  /** When the rates are from, as a Date, a timestamp or an ISO string: it is written as a time next to the rate ("updated 10:42"). */
  updatedAt?: Date | string | number;
  /** The time zone that time is written in. Default "UTC". */
  timeZone?: string;
  /** The field's name for a plain form submit: `<name>-send`, `<name>-send-currency`, `<name>-receive` and `<name>-receive-currency` go out in hidden inputs, the amounts in minor units. */
  name?: string;
  /** Turn the whole field off. */
  disabled?: boolean;
  /** The words the field says, for another language or your own voice. */
  labels?: Partial<ExchangeLabels>;
}

const textOf = (leg: Leg, locale: string): string => (leg.minor === null ? "" : formatAmount(leg.minor, currencyDigits(leg.currency), locale));

/** The currency menu of one amount: a button that opens a searchable list. */
function CurrencyMenu({ side, value, currencies, onPick, locale, labels, disabled }: { side: Side; value: string; currencies: readonly string[]; onPick: (code: string) => void; locale: string; labels: ExchangeLabels; disabled: boolean }) {
  const [open, setOpen] = useState(false);
  const codes = currencies.includes(value) ? currencies : [value, ...currencies];
  // The list is only worked out while it is open: every name is a question to Intl.
  const options = open ? codes.map((code) => ({ code, name: currencyName(code, locale) })) : [];
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          data-slot={`currency-${side}`}
          disabled={disabled}
          aria-label={`${labels.currency} (${labels[side]}): ${currencyName(value, locale)} (${value})`}
          className="inline-flex h-9 shrink-0 items-center gap-1.5 rounded-full border border-border bg-background pr-2.5 pl-3.5 text-sm font-medium tabular-nums shadow-xs outline-none transition-colors duration-150 hover:bg-muted focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/40 disabled:pointer-events-none data-[state=open]:bg-muted motion-reduce:transition-none"
        >
          {value}
          <IconChevronsUpDown aria-hidden="true" className="size-3.5 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="end" collisionPadding={8} aria-label={labels.currency} className="w-72 max-w-[calc(100vw-2rem)] overflow-hidden p-0">
        <Command loop className="rounded-none bg-transparent">
          <CommandInput placeholder={labels.search} aria-label={labels.search} />
          <CommandList>
            <CommandEmpty>{labels.empty}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => (
                <CommandItem
                  key={option.code}
                  value={option.code}
                  keywords={[option.name]}
                  onSelect={() => {
                    setOpen(false);
                    onPick(option.code);
                  }}
                  className="gap-3 pr-8"
                >
                  <span className="w-9 shrink-0 font-medium tabular-nums">{option.code}</span>
                  <span className="min-w-0 truncate text-muted-foreground">{option.name}</span>
                  {option.code === value ? (
                    <>
                      <IconCheck size={14} className="absolute right-2 text-foreground" />
                      <span className="sr-only">, selected</span>
                    </>
                  ) : null}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

/**
 * Two amounts tied together by a rate: what you send and what they receive,
 * each with its own currency menu. Type in either and the other follows at the
 * rate you pass in, worked out on whole minor units in each currency's own
 * decimals and rounded the way money is, so a yen is never in hundredths and
 * the person at the other end is never a cent short. The amount that was typed
 * last is marked Fixed. A line between the two says the rate in words ("1 EUR =
 * 1.0842 USD, updated 10:42"), a fee passed in is taken off before the rate is
 * applied and shown in its own row, and what was worked out is told to a screen
 * reader once the typing pauses. The swap button exchanges the currencies and
 * keeps the amount sent; choosing the currency the other side already has does
 * the same. Stacked in a narrow space, side by side in a wide one. It reports
 * `{ send, receive, fixed }` in minor units.
 */
export function CurrencyExchangeField({
  value,
  defaultValue,
  onValueChange,
  rates,
  currencies = DEFAULT_CURRENCIES,
  fee,
  locale = "en-US",
  min,
  max,
  updatedAt,
  timeZone = "UTC",
  name,
  disabled = false,
  labels: labelOverrides,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": labelledBy,
  ...props
}: CurrencyExchangeFieldProps) {
  const base = useId();
  const labels: ExchangeLabels = { ...DEFAULT_LABELS, ...labelOverrides };
  const [own, setOwn] = useState<ExchangeValue>(
    () =>
      defaultValue ?? {
        send: { minor: null, currency: currencies[0] ?? "EUR" },
        receive: { minor: null, currency: currencies[1] ?? currencies[0] ?? "USD" },
        fixed: "send",
      },
  );
  const state = value ?? own;
  const { value: worked, rate } = resolveValue(state, rates, fee);
  // What is typed in the fixed amount. The other amount is never typed: it is the sum, written out.
  const [draft, setDraft] = useState(() => textOf(state[state.fixed], locale));
  const [synced, setSynced] = useState(value);
  const [showLimit, setShowLimit] = useState(false);
  const [turns, setTurns] = useState(0);
  const [said, setSaid] = useState("");
  const reported = useRef<ExchangeValue | null>(null);
  const timer = useRef<number | undefined>(undefined);

  // Amounts that arrive from outside replace what is typed; an echo of what was just reported changes nothing.
  if (value !== undefined && value !== synced) {
    setSynced(value);
    const before = reported.current;
    const same = before !== null && before.fixed === value.fixed && before[value.fixed].minor === value[value.fixed].minor && before[value.fixed].currency === value[value.fixed].currency;
    if (!same) setDraft(textOf(value[value.fixed], locale));
  }

  useEffect(trackPress, []);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  // What a screen reader was told stays only while it is news; left in the live region it would be read again together with the next message.
  useEffect(() => {
    if (!said) return;
    const clear = window.setTimeout(() => setSaid(""), 5000);
    return () => window.clearTimeout(clear);
  }, [said]);

  /** Why the amount sent cannot be used, in words, or null. */
  function problemOf(sent: Leg): string | null {
    if (sent.minor === null) return null;
    const lowest = limitOf(min, sent.currency);
    const highest = limitOf(max, sent.currency);
    if (lowest !== undefined && sent.minor < lowest) return labels.atLeast(formatMoneyText(lowest, sent.currency, locale));
    if (highest !== undefined && sent.minor > highest) return labels.atMost(formatMoneyText(highest, sent.currency, locale));
    return null;
  }

  function validOf(full: ExchangeValue, found: number | null): boolean {
    return found !== null && full.send.minor !== null && full.send.minor > 0 && full.receive.minor !== null && problemOf(full.send) === null;
  }

  /** Works out the amount that follows, reports both, and returns them. */
  function write(next: ExchangeValue): ExchangeValue {
    const result = resolveValue(next, rates, fee);
    reported.current = result.value;
    if (value === undefined) setOwn(result.value);
    onValueChange?.(result.value, { valid: validOf(result.value, result.rate) });
    return result.value;
  }

  function sayLater(text: string) {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setSaid(text), 700);
  }

  function typeIn(side: Side, event: ChangeEvent<HTMLInputElement>) {
    const text = tidyTyping(event.target.value);
    const leg = state[side];
    const minor = parseAmount(text, currencyDigits(leg.currency), locale);
    setDraft(text);
    setSaid("");
    window.clearTimeout(timer.current);
    const full = write(side === "send" ? { ...state, fixed: side, send: { ...leg, minor } } : { ...state, fixed: side, receive: { ...leg, minor } });
    const other: Side = side === "send" ? "receive" : "send";
    const result = full[other];
    if (result.minor !== null) sayLater(labels.worked(labels[other], formatMoneyText(result.minor, result.currency, locale)));
  }

  /** The amount is left: it is written the locale's way, and a problem with the amount sent may now be said. */
  function settle(side: Side) {
    if (state.fixed === side) {
      const minor = parseAmount(draft, currencyDigits(state[side].currency), locale);
      setDraft(minor === null ? "" : formatAmount(minor, currencyDigits(state[side].currency), locale));
    }
    whenReleased(() => setShowLimit(true));
  }

  /** The currency of one side is changed. The amount that is fixed keeps the number in it, in the decimals of the new currency. */
  function pick(side: Side, code: string) {
    const other: Side = side === "send" ? "receive" : "send";
    if (code === state[side].currency) return;
    // Choosing what the other side already has would send and receive the same thing: the two currencies change places instead.
    if (code === state[other].currency) {
      swap();
      return;
    }
    const digits = currencyDigits(code);
    let leg: Leg = { ...state[side], currency: code };
    if (state.fixed === side) {
      const minor = parseAmount(draft, digits, locale);
      leg = { ...leg, minor };
      setDraft(minor === null ? "" : formatAmount(minor, digits, locale));
    }
    const full = write(side === "send" ? { ...state, send: leg } : { ...state, receive: leg });
    setShowLimit(true);
    const result = full[state.fixed === side ? other : side];
    if (result.minor !== null) setSaid(labels.worked(labels[state.fixed === side ? other : side], formatMoneyText(result.minor, result.currency, locale)));
  }

  /** The two currencies change places and the amount sent stays as a number. */
  function swap() {
    const sentText = state.fixed === "send" ? draft : textOf(worked.send, locale);
    const sendCurrency = state.receive.currency;
    const digits = currencyDigits(sendCurrency);
    const minor = parseAmount(sentText, digits, locale);
    setDraft(minor === null ? "" : formatAmount(minor, digits, locale));
    setTurns((count) => count + 1);
    const full = write({ send: { minor, currency: sendCurrency }, receive: { minor: null, currency: state.send.currency }, fixed: "send" });
    setSaid(labels.swapped(full.send.minor === null ? full.send.currency : formatMoneyText(full.send.minor, full.send.currency, locale), full.receive.minor === null ? full.receive.currency : formatMoneyText(full.receive.minor, full.receive.currency, locale)));
  }

  const fixedSide = state.fixed;
  const problem = showLimit ? problemOf(worked.send) : null;
  const when = updatedAt === undefined ? null : writeTime(updatedAt, locale, timeZone);
  const sentMinor = worked.send.minor;
  const feeMinor = fee !== undefined && sentMinor !== null ? feeOn(sentMinor, worked.send.currency, fee) : null;
  // What the fee is made of, when it is a share and a fixed part: "0.5% + 0.99".
  const parts: string[] = [];
  if (fee !== undefined && typeof fee === "object") {
    const flat = flatOf(fee, worked.send.currency);
    if (fee.percent) parts.push(`${new Intl.NumberFormat(locale, { maximumFractionDigits: 4 }).format(fee.percent)}%`);
    if (flat) parts.push(formatMoneyText(flat, worked.send.currency, locale));
  }
  const makeup = parts.length > 1 || (parts.length === 1 && fee !== undefined && typeof fee === "object" && fee.percent) ? parts.join(" + ") : null;
  const rateText = rate === null ? null : labels.rate(worked.send.currency, worked.receive.currency, writeRate(rate, locale));
  const rateLine =
    rateText === null ? (
      <span className="flex items-center gap-1.5">
        <IconAlertCircle aria-hidden="true" className="size-3.5 shrink-0" />
        {labels.noRate(worked.send.currency, worked.receive.currency)}
      </span>
    ) : (
      <span suppressHydrationWarning>
        <span className="font-medium text-foreground tabular-nums">{rateText}</span>
        {when ? <span>{`, ${labels.updated(when)}`}</span> : null}
      </span>
    );

  const card = (side: Side) => {
    const id = `${base}-${side}`;
    const leg = worked[side];
    const digits = currencyDigits(leg.currency);
    const isFixed = fixedSide === side;
    const flagged = side === "send" && problem !== null;
    return (
      <div
        className={cn(
          "grid grid-cols-1 gap-0.5 rounded-xl border bg-card px-4 py-3 shadow-xs @max-[17rem]:px-3 transition-[border-color,box-shadow] duration-150 has-[input:focus-visible]:border-ring has-[input:focus-visible]:ring-[3px] has-[input:focus-visible]:ring-ring/40 motion-reduce:transition-none",
          flagged ? "border-destructive has-[input:focus-visible]:border-destructive has-[input:focus-visible]:ring-destructive/30" : "border-input",
          disabled && "opacity-50",
        )}
      >
        <div className="flex min-h-5 items-center justify-between gap-2">
          <label htmlFor={id} className="text-xs font-medium text-muted-foreground">
            {labels[side]}
          </label>
          {isFixed ? (
            <span id={`${id}-fixed`} className="inline-flex items-center gap-1 text-[0.6875rem] font-medium text-muted-foreground">
              <IconLock aria-hidden="true" className="size-3" />
              {labels.fixed}
            </span>
          ) : null}
        </div>
        <div className="flex items-center gap-3">
          <input
            id={id}
            type="text"
            inputMode={digits === 0 ? "numeric" : "decimal"}
            autoComplete="off"
            autoCapitalize="off"
            spellCheck={false}
            disabled={disabled}
            placeholder={formatAmount(0, digits, locale)}
            value={isFixed ? draft : textOf(leg, locale)}
            onChange={(event) => typeIn(side, event)}
            onBlur={() => settle(side)}
            aria-invalid={flagged || undefined}
            aria-describedby={[isFixed ? `${id}-fixed` : "", side === "send" ? `${base}-problem` : "", `${base}-rate`].filter(Boolean).join(" ")}
            className="h-11 w-0 min-w-0 flex-1 bg-transparent text-[1.625rem] font-medium @max-[17rem]:text-xl tracking-[-0.02em] tabular-nums outline-none placeholder:text-muted-foreground/50 disabled:cursor-not-allowed"
          />
          <CurrencyMenu side={side} value={leg.currency} currencies={currencies} onPick={(code) => pick(side, code)} locale={locale} labels={labels} disabled={disabled} />
        </div>
      </div>
    );
  };

  return (
    <div
      data-slot="currency-exchange-field"
      role="group"
      aria-label={labelledBy ? undefined : (ariaLabel ?? labels.group)}
      aria-labelledby={labelledBy}
      className={cn("@container w-full min-w-0", className)}
      {...props}
    >
      <div className="grid grid-cols-1 gap-y-2 @lg:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] @lg:gap-x-3">
        <div className="grid min-w-0 grid-cols-1 content-start gap-1.5">
          {card("send")}
          <div id={`${base}-problem`} aria-live="polite">
            {problem ? (
              <p className="flex items-start gap-1.5 text-xs text-destructive">
                <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
                {problem}
              </p>
            ) : null}
          </div>
        </div>
        <div className="flex items-center gap-3 px-1 @lg:flex-col @lg:justify-start @lg:px-0 @lg:pt-[2.3rem]">
          <button
            type="button"
            disabled={disabled}
            aria-label={labels.swap}
            onClick={swap}
            className="grid size-9 shrink-0 place-items-center rounded-full border border-border bg-background text-muted-foreground shadow-xs outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/40 active:translate-y-px disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none"
          >
            <span className="grid rotate-90 place-items-center @lg:rotate-0">
              <IconArrowLeftRight aria-hidden="true" className="size-4 transition-[rotate] duration-300 ease-[cubic-bezier(0.2,0.7,0.2,1)] motion-reduce:transition-none" style={{ rotate: `${turns * 180}deg` }} />
            </span>
          </button>
          <p id={`${base}-rate`} className="min-w-0 text-xs text-muted-foreground @lg:hidden">
            {rateLine}
          </p>
        </div>
        <div className="grid min-w-0 grid-cols-1 content-start gap-1.5">{card("receive")}</div>
        <p className="hidden text-center text-xs text-muted-foreground @lg:col-span-3 @lg:block">{rateLine}</p>
      </div>
      {feeMinor !== null && fee !== undefined ? (
        <p className="mt-3 flex items-baseline justify-between gap-3 border-t border-border pt-3 text-xs text-muted-foreground">
          <span>{typeof fee === "object" && fee.label ? fee.label : labels.fee}</span>
          <span className="tabular-nums" suppressHydrationWarning>
            <span className="font-medium text-foreground">{formatMoneyText(feeMinor, worked.send.currency, locale)}</span>
            {makeup ? ` (${makeup})` : ""}
          </span>
        </p>
      ) : null}
      <span role="status" className="sr-only">
        {said}
      </span>
      {name ? (
        <>
          <input type="hidden" name={`${name}-send`} value={worked.send.minor ?? ""} disabled={disabled} />
          <input type="hidden" name={`${name}-send-currency`} value={worked.send.currency} disabled={disabled} />
          <input type="hidden" name={`${name}-receive`} value={worked.receive.minor ?? ""} disabled={disabled} />
          <input type="hidden" name={`${name}-receive-currency`} value={worked.receive.currency} disabled={disabled} />
        </>
      ) : null}
    </div>
  );
}

/** Which of the two amounts is meant. */
export type Side = "send" | "receive";

/** An amount and the currency it is in. */
export interface Leg {
  /** The amount in minor units, as a whole number: 1250 is 12.50 in euros and 1,250 in yen. Null while there is none. */
  minor: number | null;
  /** The ISO 4217 code: "EUR". */
  currency: string;
}

/** Both amounts, and the one that is fixed: the one that was typed last. The other is worked out from it. */
export interface ExchangeValue {
  send: Leg;
  receive: Leg;
  fixed: Side;
}

/** Rates as a table: `table.EUR.USD` is how many dollars one euro buys. A pair that is missing is taken from the other way round. */
export type RateTable = Readonly<Record<string, Readonly<Record<string, number>>>>;

/** Rates as a function: how many units of `to` one unit of `from` buys, or null when there is no rate. */
export type RateFunction = (from: string, to: string) => number | null | undefined;

export type Rates = RateTable | RateFunction;

/** What sending costs. It comes out of what is sent, before the rate is applied. */
export interface ExchangeFee {
  /** A share of the amount sent: 0.5 is half a percent. */
  percent?: number;
  /**
   * A fixed part, in minor units of the currency that is sent. A bare number counts the minor units of whichever currency is sent (99 is 0.99 in euros and 99 in yen),
   * so give one figure per currency code ({ EUR: 99, JPY: 150 }) when the field can send more than one. A currency the record does not name has no fixed part.
   */
  flat?: ExchangeLimit;
  /** What the row says, in place of "Fee". */
  label?: string;
}

/** A fee as an object, or as a function that is given what is sent and returns the fee in minor units of that currency. */
export type FeeSource = ExchangeFee | ((sent: { minor: number; currency: string }) => number);

/**
 * One limit for every currency, or one per currency code, in minor units of the currency that is sent. A bare number is read in whichever currency is sent
 * (1000 is 10.00 in euros and 1,000 in yen), so give one figure per code ({ EUR: 1000, JPY: 1600 }) when the field can send more than one.
 */
export type ExchangeLimit = number | Readonly<Record<string, number>>;

/** The words the field says, on screen and to a screen reader. Each can be replaced, for another language or your own voice. */
export interface ExchangeLabels {
  /** The name of the whole field when it has no aria-label of its own. */
  group: string;
  /** The names of the two amounts. */
  send: string;
  receive: string;
  /** The mark on the amount that is fixed. */
  fixed: string;
  /** The start of a currency menu button's name, which always ends in the chosen currency: "Currency: Euro (EUR)". */
  currency: string;
  /** What the search box in the menu asks. */
  search: string;
  /** What the menu says when no currency matches. */
  empty: string;
  /** The name of the swap button. */
  swap: string;
  /** The rate in words. `rate` is the number as it is written. */
  rate: (from: string, to: string, rate: string) => string;
  /** When the rates are from. */
  updated: (time: string) => string;
  /** Said when there is no rate between the two currencies. */
  noRate: (from: string, to: string) => string;
  /** The name of the fee row when the fee has no label of its own. */
  fee: string;
  /** What a screen reader hears once the typing pauses: the amount that was worked out. */
  worked: (name: string, amount: string) => string;
  /** What a screen reader hears after the swap button. */
  swapped: (send: string, receive: string) => string;
  /** The amount sent is below the lowest allowed. `limit` is that amount, written out. */
  atLeast: (limit: string) => string;
  /** The amount sent is above the highest allowed. */
  atMost: (limit: string) => string;
}

export const DEFAULT_LABELS: ExchangeLabels = {
  group: "Currency exchange",
  send: "You send",
  receive: "They receive",
  fixed: "Fixed",
  currency: "Currency",
  search: "Search currencies",
  empty: "No currency matches that.",
  swap: "Swap currencies",
  rate: (from, to, rate) => `1 ${from} = ${rate} ${to}`,
  updated: (time) => `updated ${time}`,
  noRate: (from, to) => `No rate for ${from} to ${to} yet.`,
  fee: "Fee",
  worked: (name, amount) => `${name} ${amount}.`,
  swapped: (send, receive) => `Currencies swapped. You send ${send}, they receive ${receive}.`,
  atLeast: (limit) => `You can send at least ${limit}.`,
  atMost: (limit) => `You can send at most ${limit}.`,
};

/** The currencies in the menus when you name none. */
export const DEFAULT_CURRENCIES: readonly string[] = ["EUR", "USD", "GBP", "CHF", "JPY", "CAD", "AUD"];

// Numbers and currencies -------------------------------------------------------------------------------------------------------

const formats = new Map<string, Intl.NumberFormat>();

/** A number format, kept: building one is far slower than using it, and a field asks on every keystroke. */
function numberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let format = formats.get(key);
  if (!format) {
    try {
      format = new Intl.NumberFormat(locale, options);
    } catch {
      format = new Intl.NumberFormat("en-US", options);
    }
    formats.set(key, format);
  }
  return format;
}

/** How many decimals a currency has: 2 for euros, 0 for yen, 3 for Kuwaiti dinars. Asked of Intl, which knows ISO 4217, so no list here goes out of date. */
export function currencyDigits(currency: string): number {
  try {
    return numberFormat("en-US", { style: "currency", currency }).resolvedOptions().maximumFractionDigits ?? 2;
  } catch {
    return 2;
  }
}

const names = new Map<string, Intl.DisplayNames>();

/** The name of a currency in the locale: "Euro", "Japanse yen". The code when the browser does not know it. */
export function currencyName(currency: string, locale: string): string {
  try {
    let display = names.get(locale);
    if (!display) {
      display = new Intl.DisplayNames(locale, { type: "currency" });
      names.set(locale, display);
    }
    return display.of(currency) ?? currency;
  } catch {
    return currency;
  }
}

/** The decimal and the grouping sign of a locale. 12345.6 is used because some locales (Spanish, Polish) only group from five digits. */
function separatorsOf(locale: string): { decimal: string; group: string } {
  const parts = numberFormat(locale, { useGrouping: true, minimumFractionDigits: 1 }).formatToParts(12345.6);
  return { decimal: parts.find((part) => part.type === "decimal")?.value ?? ".", group: parts.find((part) => part.type === "group")?.value ?? "," };
}

/**
 * Arabic-Indic and Persian digits and their separators, and the typographic
 * apostrophe, as the plain characters, so a keyboard in those scripts types an
 * amount like any other. Written by code point, so the source stays ASCII.
 */
function asciiAmount(text: string): string {
  let plain = "";
  for (const char of text) {
    const code = char.charCodeAt(0);
    if (code >= 0x660 && code <= 0x669) plain += String(code - 0x660);
    else if (code >= 0x6f0 && code <= 0x6f9) plain += String(code - 0x6f0);
    else if (code === 0x66b) plain += ".";
    else if (code === 0x66c) plain += ",";
    else if (code === 0x2019) plain += "'";
    else plain += char;
  }
  return plain;
}

/** Characters that can be part of an amount: digits, the two separators, spaces of every kind (a group sign in French and Swiss) and apostrophes. */
export function tidyTyping(raw: string): string {
  return asciiAmount(raw).replace(/[^\d.,\s']/g, "");
}

/** Which sign in the text is the decimal one, or null when there is none ("1.234.567" has only grouping). */
function decimalSign(body: string, digits: number, locale: string): string | null {
  const marks = body.match(/[.,]/g);
  if (!marks) return null;
  // Both are there ("1.234,56", "1,234.56"): the last one is the decimal sign.
  if (new Set(marks).size === 2) return body.lastIndexOf(".") > body.lastIndexOf(",") ? "." : ",";
  // The same sign twice or more is only grouping.
  if (marks.length > 1) return null;
  const mark = marks[0] ?? ".";
  const [before = "", after = ""] = body.split(mark);
  const thousand = after.length === 3 && /^[1-9]\d{0,2}$/.test(before);
  // The locale's own sign is a decimal, except for a currency with no decimals, where "1.234" can only be a thousand.
  if (mark === separatorsOf(locale).decimal) return digits === 0 && thousand ? null : mark;
  // The other sign is accepted too: "12,5" is a decimal, "1,234" a thousand.
  return thousand ? null : mark;
}

/**
 * The text as an amount in minor units, or null when it holds no number. Either
 * decimal sign is understood ("12,5" and "12.5"), and so is a grouping sign
 * ("1.250,00", "1 250,00", "1'250.00"). More decimals than the currency has are
 * rounded half up, on the digits themselves, so no float comes between.
 */
export function parseAmount(raw: string, digits: number, locale: string): number | null {
  const text = asciiAmount(raw);
  // A decimal sign in front of the first digit still counts: ",5" is a half.
  const first = text.search(/[.,]?\d/);
  if (first === -1) return null;
  const body = text.slice(first).replace(/[\s']/g, "").replace(/[^\d.,]/g, "");
  const sign = decimalSign(body, digits, locale);
  const at = sign === null ? -1 : body.lastIndexOf(sign);
  const whole = (at === -1 ? body : body.slice(0, at)).replace(/[.,]/g, "");
  const fraction = at === -1 ? "" : body.slice(at + 1).replace(/[.,]/g, "");
  let minor = Number(`${whole || "0"}${fraction.slice(0, digits).padEnd(digits, "0")}`);
  if (fraction.length > digits && fraction.charAt(digits) >= "5") minor += 1;
  return Number.isSafeInteger(minor) ? minor : null;
}

/** An amount in minor units as the locale writes a number with that many decimals: "1,250.00", "1.250,00", "1,250". */
export function formatAmount(minor: number, digits: number, locale: string): string {
  return numberFormat(locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(minor / 10 ** digits);
}

/** The same amount with its currency sign, for a message: "$1,250.00", "1.250,00 EUR" in a locale that writes it so. */
export function formatMoneyText(minor: number, currency: string, locale: string): string {
  const digits = currencyDigits(currency);
  try {
    return numberFormat(locale, { style: "currency", currency, minimumFractionDigits: digits, maximumFractionDigits: digits }).format(minor / 10 ** digits);
  } catch {
    return `${formatAmount(minor, digits, locale)} ${currency}`;
  }
}

/** An amount moved from a currency with `from` decimals to one with `to`: 1250 (12.50) is 13 in yen. Whole integers, half up, no float. */
export function rescale(minor: number, from: number, to: number): number {
  if (from === to) return minor;
  if (to > from) return minor * 10 ** (to - from);
  const divisor = 10 ** (from - to);
  return Math.floor(minor / divisor) + ((minor % divisor) * 2 >= divisor ? 1 : 0);
}

/** A rate as it is written in the line between the amounts: up to six figures, so 1.0842 and 163.27 and 0.00667 all read as they are. */
export function writeRate(rate: number, locale: string): string {
  return numberFormat(locale, { maximumSignificantDigits: 6, useGrouping: true }).format(rate);
}

/** The time of day the rates are from, in the locale and the time zone: "10:42". */
export function writeTime(moment: Date | string | number, locale: string, timeZone: string): string | null {
  const instant = new Date(moment);
  if (Number.isNaN(instant.getTime())) return null;
  try {
    return new Intl.DateTimeFormat(locale, { hour: "2-digit", minute: "2-digit", timeZone }).format(instant);
  } catch {
    return new Intl.DateTimeFormat("en-US", { hour: "2-digit", minute: "2-digit", timeZone: "UTC" }).format(instant);
  }
}

// Rates and sums ---------------------------------------------------------------------------------------------------------------

/** How many units of `to` one unit of `from` buys, or null when the rates do not say. */
export function rateBetween(rates: Rates, from: string, to: string): number | null {
  if (from === to) return 1;
  const usable = (rate: unknown): rate is number => typeof rate === "number" && Number.isFinite(rate) && rate > 0;
  if (typeof rates === "function") {
    const rate = rates(from, to);
    return usable(rate) ? rate : null;
  }
  const direct = rates[from]?.[to];
  if (usable(direct)) return direct;
  const back = rates[to]?.[from];
  return usable(back) ? 1 / back : null;
}

const SCALE = 10_000_000_000n;

/** A rate as a fraction of whole numbers, so every sum below is exact: no float ever comes between an amount and the rate. */
function fractionOf(rate: number): { n: bigint; d: bigint } {
  const [whole = "0", fraction = ""] = rate.toFixed(10).split(".");
  return { n: BigInt(`${whole}${fraction}`), d: SCALE };
}

/** a / b rounded half up, for whole numbers that are not negative. */
const divideRound = (a: bigint, b: bigint): bigint => (2n * a + b) / (2n * b);

/** a / b rounded up, for whole numbers that are not negative. */
const divideUp = (a: bigint, b: bigint): bigint => (a + b - 1n) / b;

const toSafe = (value: bigint): number | null => (value <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(value) : null);

/** The limit that applies to a currency: the number itself, or the one the record names for that code. */
export const limitOf = (limit: ExchangeLimit | undefined, currency: string): number | undefined => (typeof limit === "number" ? limit : limit?.[currency]);

/** The fixed part of a fee on an amount sent in `currency`, in minor units of that currency. */
export function flatOf(fee: ExchangeFee, currency: string): number {
  return Math.max(0, Math.round(limitOf(fee.flat, currency) ?? 0));
}

/** The fee on an amount sent, in minor units of that currency. */
export function feeOn(minor: number, currency: string, fee: FeeSource | undefined): number {
  if (fee === undefined || minor <= 0) return 0;
  if (typeof fee === "function") return Math.max(0, Math.round(fee({ minor, currency })));
  const share = Math.round(Math.max(0, fee.percent ?? 0) * 10_000);
  const percent = toSafe(divideRound(BigInt(minor) * BigInt(share), 1_000_000n)) ?? 0;
  return Math.min(minor, percent + flatOf(fee, currency));
}

/** What the other side gets for `minor` sent: the fee is taken off, then the rate applied, rounded half up in the currency's own decimals. */
export function receiveFor(minor: number, from: string, to: string, rate: number, fee: FeeSource | undefined): number | null {
  const net = Math.max(0, minor - feeOn(minor, from, fee));
  const { n, d } = fractionOf(rate);
  return toSafe(divideRound(BigInt(net) * n * 10n ** BigInt(currencyDigits(to)), d * 10n ** BigInt(currencyDigits(from))));
}

/**
 * What has to be sent for `minor` to arrive: the smallest amount that, after the
 * fee and at the rate, leaves the other side with at least that much. Rounded up,
 * so the person at the other end is never short by a cent.
 */
export function sendFor(minor: number, from: string, to: string, rate: number, fee: FeeSource | undefined): number | null {
  const { n, d } = fractionOf(rate);
  const net = toSafe(divideUp(BigInt(minor) * d * 10n ** BigInt(currencyDigits(from)), n * 10n ** BigInt(currencyDigits(to))));
  if (net === null) return null;
  // A first guess from the fee as a share and a fixed part, then moved to the exact smallest amount that works.
  let guess = net;
  if (fee !== undefined && typeof fee !== "function") {
    const share = Math.round(Math.max(0, fee.percent ?? 0) * 10_000);
    if (share >= 1_000_000) return null;
    guess = toSafe(divideUp(BigInt(net + flatOf(fee, from)) * 1_000_000n, BigInt(1_000_000 - share))) ?? net;
  } else if (typeof fee === "function") {
    guess = net + feeOn(net, from, fee);
  }
  const arrives = (sent: number) => sent - feeOn(sent, from, fee) >= net;
  for (let tries = 0; tries < 64 && !arrives(guess); tries += 1) guess += 1;
  for (let tries = 0; tries < 64 && guess > 0 && arrives(guess - 1); tries += 1) guess -= 1;
  return arrives(guess) ? guess : null;
}

/** Both amounts: the fixed one as it is, the other worked out from it, or null when there is nothing to work from or no rate. */
export function resolveValue(value: ExchangeValue, rates: Rates, fee: FeeSource | undefined): { value: ExchangeValue; rate: number | null } {
  const rate = rateBetween(rates, value.send.currency, value.receive.currency);
  const { fixed } = value;
  const known = value[fixed].minor;
  let worked: number | null = null;
  if (known !== null && rate !== null) {
    worked = fixed === "send" ? receiveFor(known, value.send.currency, value.receive.currency, rate, fee) : sendFor(known, value.send.currency, value.receive.currency, rate, fee);
  }
  return {
    rate,
    value: fixed === "send" ? { ...value, receive: { ...value.receive, minor: worked } } : { ...value, send: { ...value.send, minor: worked } },
  };
}

// A message that appears while a finger or a mouse button is still down moves the next control from under the pointer and swallows its click (the usual way
// a blur check eats a submit), so such a message waits until the press is over.
//
// A mouse press moves the focus while the button is down. A touch tap does not: it runs pointerdown, touchstart, pointerup, touchend, and only then the mouse
// events the browser makes up (mousedown, which moves the focus and blurs the field, then mouseup and click). So a press is armed by pointerdown, mousedown and
// touchstart alike, and a release only counts when no newer press began after it was announced.

/** A press that began longer ago than this is taken to be stuck (its release never arrived), not to be the one that blurred the field. */
const STALE_MS = 3000;

let pressed = false;
let pressedAt = 0;
let presses = 0;
let tracking = false;
const afterRelease: (() => void)[] = [];

/** Starts watching presses for the whole page, once. Call it from an effect. */
export function trackPress(): void {
  if (tracking) return;
  tracking = true;
  const press = () => {
    pressed = true;
    pressedAt = performance.now();
    presses += 1;
  };
  const release = () => {
    const seen = presses;
    window.setTimeout(() => {
      // Touch makes its mouse events after it has released: a press that began since then is still going on.
      if (seen !== presses) return;
      pressed = false;
      for (const run of afterRelease.splice(0)) run();
    }, 0);
  };
  // Passive: these only watch, and a touch listener that could cancel would hold the page's scrolling back.
  const options = { capture: true, passive: true };
  for (const type of ["pointerdown", "mousedown", "touchstart"] as const) document.addEventListener(type, press, options);
  for (const type of ["pointerup", "pointercancel", "mouseup", "touchend", "touchcancel", "click"] as const) document.addEventListener(type, release, options);
}

/** Runs `run` now, or, while a press is going on, as soon as it is over. */
export function whenReleased(run: () => void): void {
  if (pressed && performance.now() - pressedAt < STALE_MS) afterRelease.push(run);
  else run();
}
